export type EvidenceMatch = {
	span: SourceSpan;
	text: string;
	captures: { [key in string]: SourceSpan };
};

export type EvidenceMeasurements = {
	files_considered: bigint;
	files_read: bigint;
	files_parsed: bigint;
	transcript_bytes_read: bigint;
	transcript_bytes_parsed: bigint;
	bytes_scanned: bigint;
	bytes_included: bigint;
	local_elapsed_ms: bigint;
};

export type EvidencePiece = {
	kind: EvidenceKindName;
	where: PieceLocation;
	text: string;
	fields: { [key in FieldName]: FieldValue };
	model_view: ModelView;
};

export type EvidencePlanInput = {
	repositories: RepositoryBinding[];
	sources: { [key in SourceName]: SourceSpec };
	payload_schemas: PayloadSchemaPath[];
	cursors: ReturnedCursor[];
	declarations: EvidenceDeclaration[];
	native_queries: NativeQuery[];
	package_bindings: PackageSourceBinding[];
	limits: InvocationLimits;
	discovery: EvidenceDiscovery;
};

export type EvidencePlanOutcome =
	| {
			kind: 'prepared';
			selections: SelectionResult[];
			captures: CaptureCoverage[];
			change_selections: ResolvedChangeSelection[];
			cursors: ReturnedCursor[];
			measurements: EvidenceMeasurements;
	  }
	| {
			kind: 'incomplete';
			selections: SelectionResult[];
			captures: CaptureCoverage[];
			change_selections: ResolvedChangeSelection[];
			cursors: ReturnedCursor[];
			measurements: EvidenceMeasurements;
			diagnostics: EvidenceDiagnosticList;
	  }
	| { kind: 'refused'; diagnostics: EvidenceDiagnosticList }
	| {
			kind: 'cancelled';
			progress: EvidenceCancellationProgress;
			diagnostics: EvidenceDiagnosticList;
			measurements: EvidenceMeasurements;
	  };

export type EvidenceRequirement = 'required' | 'optional';

export type EvidenceRetryAdvice =
	| { kind: 'retry_after'; milliseconds: bigint }
	| { kind: 'repair_request' }
	| { kind: 'repair_source' }
	| { kind: 'capture_again' }
	| { kind: 'repair_configuration' }
	| { kind: 'restore_provider_access' }
	| { kind: 'do_not_retry' }
	| { kind: 'unknown' };

export type EvidenceRuleId = string;

