export type EvidenceSelector =
	| {
			kind: 'related_units';
			query: RelationshipQuery;
			chunk_settings: ChunkSettings;
			minimum_related_units: bigint;
	  }
	| { kind: 'paragraph'; repository_id: RepositoryId; source_path: string; target_id: TargetId }
	| { kind: 'file_text'; repository_id: RepositoryId; source_path: string }
	| { kind: 'literal_text'; repository_id: RepositoryId; paths: QueryPath[]; text: string }
	| { kind: 'regex_text'; repository_id: RepositoryId; paths: QueryPath[]; pattern: string }
	| {
			kind: 'ast_pattern';
			repository_id: RepositoryId;
			paths: QueryPath[];
			language: string;
			pattern: string;
	  };

/**  Recursive JSON content. This is data, never a declaration or an executable expression. */
