export type FieldUnavailable =
	| 'selection_pending'
	| 'selection_unavailable'
	| 'empty_target'
	| 'outside_root'
	| 'frontmatter_malformed'
	| 'not_a_string'
	| 'unreadable'
	| 'target_kind_missing'
	| 'containing_field_unavailable'
	| 'capture_source_unavailable'
	| 'attachment_unavailable';

export type FieldValue =
	| { state: 'text'; value: string; spans: SourceSpan[] }
	| { state: 'texts'; cut?: boolean; values: string[]; spans: SourceSpan[] }
	| { state: 'document'; cut?: boolean; path: string; values: string[]; spans: SourceSpan[] }
	| { state: 'missing_document'; candidates: string[] }
	| { state: 'targets'; values: LoadTarget[] }
	| { state: 'absent' }
	| { state: 'unavailable'; reason: FieldUnavailable };

export type FileCount = {
	file: string;
	kinds: { [key in EvidenceKindName]: KindCount };
};

export type FilterAnswer = {
	reads_sha256?: string | null;
	filter: FilterName;
	folder: string;
	input_cut: boolean;
	requested_model: ModelName;
	resolved_model: ModelName | null;
} & FilterAnswerState;

export type FilterAnswerState =
	| {
			state: 'unavailable';
			reason: WorkUnavailableReason;
			field?: FieldName | null;
			path: StepName[];
			answers: { [key in QuestionName]: JudgmentAnswer };
	  }
	| {
			state: 'judged';
			label: ChoiceLabel;
			path: StepName[];
			answers: { [key in QuestionName]: JudgmentAnswer };
	  }
	| {
			state: 'unsure';
			step: StepName;
			path: StepName[];
			answers: { [key in QuestionName]: JudgmentAnswer };
	  }
	| {
			state: 'incomplete';
			reason: FilterIncomplete;
			field?: FieldName | null;
			path: StepName[];
			answers: { [key in QuestionName]: JudgmentAnswer };
	  };

export type FilterIncomplete =
	| { kind: 'undescribed' }
	| { kind: 'ambiguous' }
	| { kind: 'reads_absent' }
	| { kind: 'reads_unavailable'; reason: FieldUnavailable }
	| { kind: 'reads_too_large' }
	| { kind: 'request'; reason: RulebookIncompleteReason };

export type FilterName = string;

export type FilterSkip = {
	locations: PieceLocation[];
	rule: RuleId;
	file: string;
	filter: FilterName;
	folder: string | null;
	why: FilterSkipReason;
	path: StepName[];
	answers: { [key in QuestionName]: JudgmentAnswer };
};

export type FilterSkipReason = 'unsure' | 'incomplete' | 'no_folder';

export type FilterWire = {
	per: string;
	reads: ReadsSpec;
	labels: ChoiceLabel[];
	questions: { [key in QuestionName]: JudgmentQuestion };
	decision: DecisionGraphWire;
	reference?: { [key in string]: StructuredJson };
};

export type FindingRoute = {
	finding: string;
	severity?: Severity | null;
	at?: FieldName | null;
	locate?: Locator | null;
};

export type FrontmatterFieldContent =
	| {
			kind: 'present';
			source: SourceRef;
			field: string;
			value: EvidenceStructuredJson;
			/**  The YAML decoder's reference span, mapped to the original document. */
			span: SourceSpan;
	  }
	| { kind: 'absent'; source: SourceRef; field: string; frontmatter_span: SourceSpan }
	| {
			kind: 'block_unavailable';
			source: SourceRef;
			field: string;
			reason: FrontmatterUnavailableReason;
			diagnostics: EvidenceDiagnosticList;
	  };

export type FrontmatterFieldLocation =
	| { kind: 'present'; span: SourceSpan }
	| { kind: 'absent'; frontmatter_span: SourceSpan }
	| { kind: 'block_unavailable'; reason: FrontmatterUnavailableReason };

export type FrontmatterUnavailableReason = 'missing' | 'malformed';

export type GeneralRuleCall<TOutcome> =
	| { kind: 'received'; outcome: TOutcome }
	| { kind: 'failed'; failure: SdkFailure };

export type GitObjectId = string;

export type GlobPattern = string;

export type GraphLanguage = 'rust' | 'typescript' | 'tsx';

export type GroupBinding =
	| { kind: 'bound' }
